# System.Runtime.Intrinsics.X86.Sse41 — the widening conversions PMOVSX / PMOVZX, in the
# source element's signedness, from a register or from memory. The memory forms read only
# the bytes the result needs (8, 4 or 2), which the load spells, then convert.
target = sse4.1
ConvertToVector128Int16(v128{T}) @ref(Vector128.WidenLower($0).AsInt16()) = _mm_cvt{ep}_epi16($0) for T in i8,u8
ConvertToVector128Int16(p{T}) @ref(Vector128.WidenLower(Vector128.Load($0)).AsInt16()) = _mm_cvt{ep}_epi16(_mm_loadl_epi64((const __m128i*)$0)) for T in i8,u8
ConvertToVector128Int32(v128{T}) @ref(Vector128.WidenLower($0).AsInt32()) = _mm_cvt{ep}_epi32($0) for T in i16,u16
ConvertToVector128Int32(v128{T}) @ref(Vector128.WidenLower(Vector128.WidenLower($0)).AsInt32()) = _mm_cvt{ep}_epi32($0) for T in i8,u8
ConvertToVector128Int32(p{T}) @ref(Vector128.WidenLower(Vector128.Load($0)).AsInt32()) = _mm_cvt{ep}_epi32(_mm_loadl_epi64((const __m128i*)$0)) for T in i16,u16
ConvertToVector128Int32(p{T}) @ref(Vector128.WidenLower(Vector128.WidenLower(Vector128.Load($0))).AsInt32()) = _mm_cvt{ep}_epi32(_mm_loadu_si32($0)) for T in i8,u8
ConvertToVector128Int64(v128{T}) @ref(Vector128.WidenLower($0).AsInt64()) = _mm_cvt{ep}_epi64($0) for T in i32,u32
ConvertToVector128Int64(v128{T}) @ref(Vector128.WidenLower(Vector128.WidenLower($0)).AsInt64()) = _mm_cvt{ep}_epi64($0) for T in i16,u16
ConvertToVector128Int64(v128{T}) @ref(Vector128.WidenLower(Vector128.WidenLower(Vector128.WidenLower($0))).AsInt64()) = _mm_cvt{ep}_epi64($0) for T in i8,u8
ConvertToVector128Int64(p{T}) @ref(Vector128.WidenLower(Vector128.Load($0)).AsInt64()) = _mm_cvt{ep}_epi64(_mm_loadl_epi64((const __m128i*)$0)) for T in i32,u32
ConvertToVector128Int64(p{T}) @ref(Vector128.WidenLower(Vector128.WidenLower(Vector128.Load($0))).AsInt64()) = _mm_cvt{ep}_epi64(_mm_loadu_si32($0)) for T in i16,u16
ConvertToVector128Int64(p{T}) @ref(Vector128.WidenLower(Vector128.WidenLower(Vector128.WidenLower(Vector128.Load($0)))).AsInt64()) = _mm_cvt{ep}_epi64(_mm_loadu_si16($0)) for T in i8,u8
